/*
 * Shown in case Azure Container Instances are at capacity.
 * This is a temporary state that should be resolved automatically.
 */

import {Banner} from '@primer/react'

export function UserRateLimitedBanner() {
  const description = 'Your request has been rate-limited. Please try again later.'
  const title = 'Your request has been rate-limited.'
  const variant = 'info'

  return (
    <Banner
      className="rounded-0"
      style={{outline: 'none'}}
      description={description}
      hideTitle
      title={title}
      variant={variant}
    />
  )
}
