import {useCurrentUser} from '@github-ui/current-user'
import {Banner, Label} from '@primer/react'

import {SPARK_LIVE_PREVIEW_IFRAME_ID} from '../../workbench/components/PreviewArea/Constants'

function RefreshAction() {
  return <Banner.PrimaryAction onClick={() => window.location.reload()}>Refresh</Banner.PrimaryAction>
}

function StaffForceIFrameAction() {
  const currentUser = useCurrentUser()
  return currentUser?.isStaff ? (
    <Banner.PrimaryAction
      onClick={() => {
        const iframe = document.getElementById(SPARK_LIVE_PREVIEW_IFRAME_ID)
        iframe?.style.setProperty('opacity', '1')
        iframe?.style.setProperty('z-index', '1000')
      }}
    >
      {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
      <span className="mr-2">Force Live IFrame</span>
      <Label variant="attention">Staff</Label>
    </Banner.PrimaryAction>
  ) : null
}

export function ConnectionReloadBanner() {
  return (
    <Banner
      variant="critical"
      title="Connection error"
      className="rounded-0"
      style={{outline: 'none'}}
      hideTitle
      description="Live preview is interrupted. Try refreshing the page to reconnect."
      primaryAction={<RefreshAction />}
      secondaryAction={<StaffForceIFrameAction />}
    />
  )
}
