import {isFeatureEnabled} from '@github-ui/feature-flags'
import {encodePart} from '@github-ui/paths'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {useNavigate} from '@github-ui/use-navigate'
import {createContext, use, useCallback, useEffect, useMemo, useRef, useState} from 'react'

import {useWorkbenchQuery} from '../hooks/use-workbench-query'
import type {Workbench, WorkbenchRoutePayload} from '../types/workbench-types'

export const sparkPathRegex = /^\/spark\/[^/]+\/[^/]+$/
export const sparkFilePathRegex = /^\/spark\/[^/]+\/[^/]+\/file\//
export const initialName = 'New spark'
export const initialDescription = ''
export const initialDeployUrl = ''

export function WorkbenchContextProvider({children}: {children: React.ReactNode}) {
  const navigate = useNavigate()
  const {workbench: initialWorkbench} = useRoutePayload<WorkbenchRoutePayload>()

  const {data: workbench, refetch} = useWorkbenchQuery(initialWorkbench.id, initialWorkbench)

  const [name, setName] = useState<string>(workbench.name || initialName)
  const [description, setDescription] = useState<string>(workbench.description || initialDescription)
  const createdAt = workbench.createdAt
  const [updatedAt, setUpdatedAt] = useState<string>(workbench.updatedAt)
  const [repositoryUrl, setRepositoryUrl] = useState<string | undefined>(workbench.repositoryUrl)

  const runtimePermanentName = workbench.runtime.app.permanentName
  const [friendlyName, setFriendlyName] = useState<string>(workbench.runtime.app.friendlyName)

  const [isLoadingFromModel, setIsLoadingFromModel] = useState(false)
  const billableOwner = workbench.billableOwner

  const sparkBaseUrl = useCallback((spark: Workbench) => {
    const runtimeApp = spark.runtime.app

    // Feature flag controls old vs new behavior
    if (isFeatureEnabled('copilot_spark_handle_nil_friendly_name')) {
      // NEW BEHAVIOR: Handle nil friendly_name and avoid permanent_name that looks like UUID
      let identifier = runtimeApp.friendlyName

      // If friendly_name is empty or equals permanent_name, fall back to UUID
      // This handles legacy sparks and transitional states during rename
      if (!identifier || identifier === runtimeApp.permanentName) {
        identifier = spark.id
      }

      return `/spark/${spark.billableOwner.login}/${encodeURIComponent(identifier)}`
    } else {
      // OLD BEHAVIOR: Just use friendlyName directly (no fallbacks)
      return `/spark/${spark.billableOwner.login}/${encodeURIComponent(runtimeApp.friendlyName)}`
    }
  }, [])

  const sparkFileUrl = useCallback(
    ({sparkId, path}: {sparkId: string; path: string}) => {
      // Feature flag controls old vs new behavior
      if (isFeatureEnabled('copilot_spark_handle_nil_friendly_name')) {
        // NEW BEHAVIOR: Always include owner, handle transitional states
        // Use friendlyName if available, but fall back to UUID if:
        // 1. friendlyName is empty/null
        // 2. friendlyName equals runtimePermanentName (transitional state)
        const identifier = friendlyName && friendlyName !== runtimePermanentName ? friendlyName : sparkId
        return `/spark/${billableOwner.login}/${encodeURIComponent(identifier)}/file/${encodePart(path)}`
      } else {
        // OLD BEHAVIOR: Use friendlyName if available, otherwise old pattern without owner
        if (friendlyName) {
          return `/spark/${billableOwner.login}/${encodeURIComponent(friendlyName)}/file/${encodePart(path)}`
        }
        return `/spark/${encodeURIComponent(sparkId)}/file/${encodePart(path)}`
      }
    },
    [billableOwner, friendlyName, runtimePermanentName],
  )

  const [isMobileSidebarOpen, setIsMobileSidebarOpen] = useState(false)
  const initialPromptSubmittedRef = useRef(false)

  // Update the URL to include the friendlyName, when we have it
  useEffect(() => {
    // Feature flag controls old vs new behavior
    if (isFeatureEnabled('copilot_spark_handle_nil_friendly_name')) {
      // NEW BEHAVIOR: Navigate to friendlyName URL, but skip transitional states
      if (!friendlyName) {
        return
      }

      // Skip if friendly_name equals permanent_name (transitional state)
      // This prevents navigation during the rename process when friendly_name
      // is initially set to the same value as permanent_name
      if (friendlyName === runtimePermanentName) {
        return
      }

      const currentPath = window.location.pathname
      const pattern = new RegExp(`/spark/${billableOwner.login}/[^/]+`)
      if (pattern.test(currentPath)) {
        // Replace the matching portion with the new path containing friendlyName
        const newPath = currentPath.replace(
          pattern,
          `/spark/${billableOwner.login}/${encodeURIComponent(friendlyName)}`,
        )
        if (newPath === currentPath) return
        navigate(newPath, {replace: true})
      }
    } else {
      // OLD BEHAVIOR: Simple navigation to friendlyName URL
      if (!friendlyName) {
        return
      }

      const currentPath = window.location.pathname
      const pattern = new RegExp(`/spark/${billableOwner.login}/[^/]+`)
      if (pattern.test(currentPath)) {
        // Replace the matching portion with the new path containing friendlyName
        const newPath = currentPath.replace(
          pattern,
          `/spark/${billableOwner.login}/${encodeURIComponent(friendlyName)}`,
        )
        if (newPath === currentPath) return
        navigate(newPath, {replace: true})
      }
    }
  }, [friendlyName, runtimePermanentName, navigate, billableOwner])

  const value = useMemo(() => {
    return {
      id: workbench.id,
      createdAt,
      updatedAt,
      setUpdatedAt,
      name,
      setName,
      description,
      setDescription,
      repositoryUrl,
      setRepositoryUrl,
      runtimePermanentName,
      friendlyName,
      setFriendlyName,
      deploy: workbench.deploy,
      isMobileSidebarOpen,
      setIsMobileSidebarOpen,
      isLoadingFromModel,
      setIsLoadingFromModel,
      initialPromptSubmittedRef,
      sparkFileUrl,
      sparkBaseUrl,
      billableOwner,
      refetch,
    } satisfies WorkbenchContextData
  }, [
    workbench.id,
    workbench.deploy,
    createdAt,
    updatedAt,
    name,
    description,
    repositoryUrl,
    runtimePermanentName,
    friendlyName,
    isMobileSidebarOpen,
    isLoadingFromModel,
    sparkFileUrl,
    sparkBaseUrl,
    billableOwner,
    refetch,
  ])
  return <WorkbenchContext value={value}>{children}</WorkbenchContext>
}
export const WorkbenchContext = createContext<WorkbenchContextData | undefined>(undefined)
export function useWorkbenchContext() {
  const context = use(WorkbenchContext)
  if (!context) {
    throw new Error('useWorkbenchContext must be used within a WorkbenchContextProvider')
  }
  return context
}

export type WorkbenchContextData = {
  id: string
  createdAt: string
  updatedAt: string
  setUpdatedAt: (value: string) => void
  name: string
  setName: (value: string) => void
  description: string
  setDescription: (value: string) => void
  repositoryUrl: string | undefined
  setRepositoryUrl: (value: string) => void
  runtimePermanentName: string
  friendlyName: string
  deploy: Workbench['deploy']
  setFriendlyName: (value: string) => void
  isMobileSidebarOpen: boolean
  setIsMobileSidebarOpen: (value: boolean) => void
  isLoadingFromModel: boolean
  setIsLoadingFromModel: (value: boolean | ((prev: boolean) => boolean)) => void
  initialPromptSubmittedRef: React.RefObject<boolean>
  sparkFileUrl: (args: {sparkId: string; path: string}) => string
  sparkBaseUrl: (spark: Workbench) => string
  billableOwner: {
    id: number
    login: string
    type: 'User' | 'Organization'
  }
  refetch: () => void
}
