import {Banner} from '@primer/react'

function PrimaryAction() {
  return <Banner.PrimaryAction onClick={() => window.location.reload()}>Refresh</Banner.PrimaryAction>
}

export function AgentServerErrorBanner() {
  return (
    <Banner
      variant="critical"
      title="Agent error"
      className="rounded-0"
      hideTitle
      description="Error generating a response. Try refreshing the page to retry."
      primaryAction={<PrimaryAction />}
    />
  )
}
